package org.usbworkbench;
import java.io.*;import java.nio.charset.*;import java.util.*;
/** ISO9660/Joliet, including adjacent level-3 multi-extent files. No Rock Ridge symlink traversal. */
final class Iso9660Image {
 private static long both32(byte[] b,int at)throws IOException{long little=OpticalImage.u32(b,at),big=0;for(int i=0;i<4;i++)big=(big<<8)|(b[at+4+i]&255);if(little!=big)throw new IOException("ISO_ENDIAN");return little;}
 private static int both16(byte[] b,int at)throws IOException{int n=OpticalImage.u16(b,at),big=((b[at+2]&255)<<8)|(b[at+3]&255);if(n!=big)throw new IOException("ISO_ENDIAN");return n;}
 private static final class Record {boolean dir,multi;String name;long offset,size;Record(byte[] b,int at,int length,boolean joliet,long volume)throws IOException{if(length<34||at+length>b.length)throw new IOException("ISO_RECORD");int chars=b[at+32]&255;if(chars==0||33+chars>length)throw new IOException("ISO_RECORD");int flags=b[at+25]&255;dir=(flags&2)!=0;multi=(flags&128)!=0;if((flags&4)!=0||b[at+26]!=0||b[at+27]!=0||both16(b,at+28)!=1)throw new IOException("ISO_UNSUPPORTED");if(chars==1&&(b[at+33]==0||b[at+33]==1))name="";else{name=OpticalImage.decode(b,at+33,chars,joliet?StandardCharsets.UTF_16BE:StandardCharsets.US_ASCII);int semi=name.lastIndexOf(';');if(semi>=0&&name.substring(semi+1).matches("[0-9]+"))name=name.substring(0,semi);if(!joliet&&name.endsWith("."))name=name.substring(0,name.length()-1);}size=both32(b,at+10);long block=both32(b,at+2)+(b[at+1]&255);offset=block*2048;if(offset>volume||size>volume-offset||dir&&multi)throw new IOException("IMAGE_BOUNDS");}}
 public static OpticalImage.Manifest scan(OpticalImage.Source source,DiskTools.Progress p)throws IOException{
  byte[] primary=null,supplement=null;for(int i=16;i<80&&((long)i+1)*2048<=source.size();i++){byte[] b=OpticalImage.bytes(source,(long)i*2048,2048);if(!new String(b,1,5,StandardCharsets.US_ASCII).equals("CD001"))continue;int type=b[0]&255;if(b[6]!=1)throw new IOException("ISO_VERSION");if(type==1)primary=b;if(type==2&&b[88]=='%'&&b[89]=='/'&&(b[90]=='@'||b[90]=='C'||b[90]=='E'))supplement=b;if(type==255)break;}
  if(primary==null)throw new IOException("NOT_ISO");boolean joliet=supplement!=null;byte[] chosen=joliet?supplement:primary;long volume=both32(chosen,80)*2048;if(volume>source.size()||volume<17*2048||both16(chosen,128)!=2048)throw new IOException("IMAGE_BOUNDS");Record root=new Record(chosen,156,chosen[156]&255,joliet,volume);if(!root.dir)throw new IOException("ISO_RECORD");OpticalImage.Manifest result=new OpticalImage.Manifest(joliet?"Joliet / ISO9660":"ISO9660");OpticalImage.Budget budget=new OpticalImage.Budget();List<OpticalImage.Entry> pending=new ArrayList<>();pending.add(new OpticalImage.Entry("",true,root.size,Arrays.asList(new OpticalImage.Range(root.offset,root.size))));Set<String> directories=new HashSet<>();
  for(int index=0;index<pending.size();index++){OpticalImage.Entry dir=pending.get(index);p.update(index,-1);if(dir.size>OpticalImage.MAX_DIRECTORY)throw new IOException("IMAGE_LIMIT");String identity=dir.ranges.get(0).offset+":"+dir.size;if(!directories.add(identity))throw new IOException("IMAGE_CYCLE");budget.metadata(dir.size);byte[] data=new byte[(int)dir.size];OpticalImage.read(source,dir,0,data,0,data.length);String multiPath=null;long multiSize=0;List<OpticalImage.Range> pieces=new ArrayList<>();
   for(int at=0;at<data.length;){int len=data[at]&255;if(len==0){int end=Math.min(data.length,((at/2048)+1)*2048);for(int off=at;off<end;off++)if(data[off]!=0)throw new IOException("ISO_RECORD");at=end;continue;}if(at%2048+len>2048)throw new IOException("ISO_RECORD");Record r=new Record(data,at,len,joliet,volume);at+=len;if(r.name.isEmpty())continue;String path=OpticalImage.safe(dir.path,r.name);if(multiPath!=null&&!multiPath.equals(path))throw new IOException("ISO_MULTI");if(r.dir){OpticalImage.Entry child=new OpticalImage.Entry(path,true,r.size,Arrays.asList(new OpticalImage.Range(r.offset,r.size)));result.add(child);pending.add(child);continue;}if(multiPath==null){multiPath=path;multiSize=0;pieces=new ArrayList<>();}if(pieces.size()>=65536||r.size>Long.MAX_VALUE-multiSize)throw new IOException("IMAGE_LIMIT");pieces.add(new OpticalImage.Range(r.offset,r.size));multiSize+=r.size;if(!r.multi){result.add(new OpticalImage.Entry(path,false,multiSize,pieces));multiPath=null;}}
   if(multiPath!=null)throw new IOException("ISO_MULTI");
  }return result;
 }
}
